-- Sri Bairavar Phase 1 schema. Run in Supabase SQL Editor; review before production use.
create extension if not exists pgcrypto;
create table if not exists public.customers (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, phone text not null, whatsapp text, email text, customer_type text not null default 'INDIVIDUAL', notes text, created_at timestamptz not null default now());
create table if not exists public.vendors (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, name text not null, phone text not null, whatsapp text, address text, notes text, active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.vehicles (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, vendor_id uuid references public.vendors(id) on delete set null, registration_no text not null, category text not null, seats integer, ac_type text, active boolean not null default true, notes text, created_at timestamptz not null default now(), unique(owner_id, registration_no));
create table if not exists public.bookings (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, booking_ref text unique, customer_id uuid references public.customers(id) on delete set null, customer_name text not null, customer_phone text not null, service_type text not null default 'Outstation', pickup text not null, destination text not null, pickup_at timestamptz not null, return_at timestamptz, passengers integer not null default 1 check(passengers > 0), vehicle_id uuid references public.vehicles(id) on delete set null, vendor_id uuid references public.vendors(id) on delete set null, driver_name text, driver_phone text, customer_amount numeric(12,2) not null default 0 check(customer_amount >= 0), vendor_cost numeric(12,2) not null default 0 check(vendor_cost >= 0), booking_status text not null default 'NEW', payment_status text not null default 'UNPAID', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create sequence if not exists public.booking_ref_seq start 1;
create or replace function public.set_booking_ref() returns trigger language plpgsql as $$ begin if new.booking_ref is null or new.booking_ref = '' then new.booking_ref := 'SBT-' || to_char(current_date,'YYYY') || '-' || lpad(nextval('public.booking_ref_seq')::text,5,'0'); end if; new.updated_at := now(); return new; end; $$;
drop trigger if exists booking_ref_trigger on public.bookings;
create trigger booking_ref_trigger before insert or update on public.bookings for each row execute function public.set_booking_ref();
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, booking_id uuid not null references public.bookings(id) on delete cascade, direction text not null check(direction in ('CUSTOMER_RECEIPT','VENDOR_PAYMENT')), amount numeric(12,2) not null check(amount > 0), payment_mode text not null, transaction_ref text, paid_at timestamptz not null default now(), notes text, created_at timestamptz not null default now());
create table if not exists public.expenses (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, booking_id uuid not null references public.bookings(id) on delete cascade, category text not null, amount numeric(12,2) not null check(amount >= 0), spent_at timestamptz not null default now(), notes text, created_at timestamptz not null default now());
create table if not exists public.booking_activity (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade, booking_id uuid not null references public.bookings(id) on delete cascade, action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.customers enable row level security; alter table public.vendors enable row level security; alter table public.vehicles enable row level security; alter table public.bookings enable row level security; alter table public.payments enable row level security; alter table public.expenses enable row level security; alter table public.booking_activity enable row level security;
do $$ declare t text; begin foreach t in array array['customers','vendors','vehicles','bookings','payments','expenses','booking_activity'] loop execute format('drop policy if exists owner_all on public.%I',t); execute format('create policy owner_all on public.%I for all to authenticated using (owner_id = auth.uid()) with check (owner_id = auth.uid())',t); end loop; end $$;
create index if not exists bookings_owner_created_idx on public.bookings(owner_id,created_at desc); create index if not exists bookings_owner_date_idx on public.bookings(owner_id,pickup_at); create index if not exists payments_booking_idx on public.payments(booking_id); create index if not exists expenses_booking_idx on public.expenses(booking_id);
-- Create the single admin user manually in Supabase Auth; disable public sign-ups. Never expose service-role keys in browser code.
